window.mobilityMock={analyze(text){const t=text.replace(/\s/g,'');let score={D:1,S:1,R:1},tags=[];if(/무릎|관절|허리|경사|언덕|계단|휠체어/.test(t)){score.S+=3;tags.push('경사 회피')}if(/벤치|휴식|쉬|피곤|오래걷/.test(t)){score.R+=3;tags.push('휴식 공간')}if(/임산|짧게|거리|걷기힘|아이|유모차/.test(t)){score.D+=3;tags.push('이동 거리')}if(/휠체어/.test(t))tags.push('계단 제외');if(!tags.length)tags=['편안한 이동'];return{score,tags}},routes:[{id:'rest',name:'완만한 휴식 경로',distance:'1.4 km',slope:'2.1°',rest:'360 m',time:'22분',desc:'완만한 보도와 벤치 2곳을 지나는 길'},{id:'short',name:'가장 짧은 경로',distance:'1.1 km',slope:'5.8°',rest:'720 m',time:'18분',desc:'언덕과 계단이 포함된 빠른 길'},{id:'flat',name:'평지 우선 경로',distance:'1.7 km',slope:'1.4°',rest:'580 m',time:'27분',desc:'경사는 가장 낮지만 돌아가는 길'}],select(score){const v={rest:{D:1.4,S:2.1,R:.36},short:{D:1.1,S:5.8,R:.72},flat:{D:1.7,S:1.4,R:.58}};return this.routes.slice().sort((a,b)=>score.D*(v[a.id].D-v[b.id].D)+score.S*(v[a.id].S-v[b.id].S)+score.R*(v[a.id].R-v[b.id].R))}};
